using System;
using System.Collections;
using System.Collections.Generic;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

public class MenuManagerCanvasGroup : ReferenceSingleton<MenuManagerCanvasGroup>
{
	[SerializeField]
	private GameObjectReference omenRewardPanelReference;

	[SerializeField]
	private GameObjectReference mapCanvasReference;

	[SerializeField]
	private GameObjectReference diceRewardCanvasReference;

	[SerializeField]
	private GameObjectReference scenarioReference;

	[SerializeField]
	private CameraReference diceCameraReference;

	[SerializeField]
	private GameObjectReference[] rewardsObjects;

	[SerializeField]
	private List<GameObjectReference> gameplayCanvasGroup;

	public List<GameObjectReference> canvasListGameobject;

	private bool isOnBattle;

	private GameObject menuStack;

	public void SetOnIsOnBattle(bool value)
	{
		isOnBattle = value;
	}

	private void Start()
	{
		UnityEngine.Object.Destroy(base.gameObject);
	}

	public void EnableAllGameplayMenus(bool disableCamera)
	{
		foreach (GameObjectReference item in gameplayCanvasGroup)
		{
			item.value.GetComponent<CanvasGroup>().alpha = 1f;
		}
		EnableScenario(delegate(string value)
		{
			Debug.Log(value);
		});
		EnablePlayer(delegate(string value)
		{
			Debug.Log(value);
		});
		if (disableCamera)
		{
			EnableCameraDice(delegate(string value)
			{
				Debug.Log(value);
			});
		}
	}

	public void DisableAllGameplayMenus(bool disableCamera)
	{
		foreach (GameObjectReference item in gameplayCanvasGroup)
		{
			item.value.GetComponent<CanvasGroup>().alpha = 0f;
		}
		DisableScenario(delegate(string value)
		{
			Debug.Log(value);
		});
		DisablePlayer(delegate(string value)
		{
			Debug.Log(value);
		});
		if (disableCamera)
		{
			DisableCameraDice(delegate(string value)
			{
				Debug.Log(value);
			});
		}
	}

	public void EnableLowerMenus(bool enableCamera)
	{
		for (int i = 1; i < gameplayCanvasGroup.Count; i++)
		{
			gameplayCanvasGroup[i].value.GetComponent<CanvasGroup>().alpha = 1f;
		}
		EnableScenario(delegate(string value)
		{
			Debug.Log(value);
		});
		EnablePlayer(delegate(string value)
		{
			Debug.Log(value);
		});
		if (enableCamera)
		{
			EnableCameraDice(delegate(string value)
			{
				Debug.Log(value);
			});
		}
	}

	public void DisableLowerMenus(bool disableCamera)
	{
		for (int i = 1; i < gameplayCanvasGroup.Count; i++)
		{
			gameplayCanvasGroup[i].value.GetComponent<CanvasGroup>().alpha = 0f;
		}
		DisableScenario(delegate(string value)
		{
			Debug.Log(value);
		});
		DisablePlayer(delegate(string value)
		{
			Debug.Log(value);
		});
		if (disableCamera)
		{
			DisableCameraDice(delegate(string value)
			{
				Debug.Log(value);
			});
		}
	}

	public void DisableMapCanvas(Action<bool> disableMap)
	{
		if (mapCanvasReference.value.GetComponentInChildren<MapManager>() == null)
		{
			disableMap(obj: false);
			Debug.Log("[MenuManagerCanvasGroup] Map Canvas is already disable");
			return;
		}
		mapCanvasReference.value.GetComponent<CanvasGroup>().alpha = 0f;
		gameplayCanvasGroup[0].value.GetComponent<CanvasGroup>().alpha = 0f;
		disableMap(obj: true);
		Debug.Log("[MenuManagerCanvasGroup] Map Canvas Disable");
	}

	public void EnableMapCanvas()
	{
		gameplayCanvasGroup[0].value.GetComponent<CanvasGroup>().alpha = 1f;
		mapCanvasReference.value.GetComponent<CanvasGroup>().alpha = 1f;
	}

	public void DisableGameobjectReference(GameObjectReference currentGameObject, Action<bool> disableObject)
	{
		if (!(currentGameObject.value == null))
		{
			CanvasGroup component = currentGameObject.value.GetComponent<CanvasGroup>();
			if (component.alpha == 0f)
			{
				disableObject?.Invoke(obj: false);
				Debug.Log("[MenuManagerCanvasGroup] GameobjectReference is already disable");
			}
			else
			{
				Debug.Log("[MenuManagerCanvasGroup] GameobjectReference Disable");
				component.alpha = 0f;
				disableObject?.Invoke(obj: true);
			}
		}
	}

	public void EnableGameobjectReference(GameObjectReference currentGameObject)
	{
		if (!(currentGameObject.value == null))
		{
			currentGameObject.value.GetComponent<CanvasGroup>().alpha = 1f;
		}
	}

	public void DisableScenario(Action<string> callback)
	{
		try
		{
			if (scenarioReference.value != null)
			{
				scenarioReference.value.gameObject.SetActive(value: false);
				for (int i = 0; i < rewardsObjects.Length; i++)
				{
					if (rewardsObjects[i].value != null)
					{
						rewardsObjects[i].value.gameObject.SetActive(value: false);
					}
				}
				callback("Sucefull DisableScenario  and rewards characters");
			}
			else
			{
				callback("Error On DisableScenario and rewards characters");
				StartCoroutine(DisableScenarioCoroutine(callback));
			}
		}
		catch (Exception ex)
		{
			callback?.Invoke("Error Menu Manager Canvas Group: " + ex.Message);
		}
	}

	public void EnableScenario(Action<string> callback)
	{
		try
		{
			if (scenarioReference.value != null)
			{
				scenarioReference.value.gameObject.SetActive(value: true);
				for (int i = 0; i < rewardsObjects.Length; i++)
				{
					if (rewardsObjects[i].value != null)
					{
						rewardsObjects[i].value.gameObject.SetActive(value: true);
					}
				}
				callback?.Invoke("Sucefull EnableScenario");
			}
			else
			{
				callback?.Invoke("Error scenarioReference is null");
			}
		}
		catch (Exception ex)
		{
			callback?.Invoke("Error Menu Manager Canvas Group: " + ex.Message);
		}
	}

	private IEnumerator DisableScenarioCoroutine(Action<string> callback)
	{
		yield return new WaitForSeconds(0.2f);
		DisableScenario(callback);
	}

	private void DisablePlayer(Action<string> callback)
	{
		try
		{
			List<GameObject> activeCompanions = ReferenceSingleton<AssetsReference>.Instance.CurrentCompanions.ActiveCompanions;
			for (int i = 0; i < activeCompanions.Count; i++)
			{
				Transform transform = activeCompanions[i].transform.Find("CorruptionGaugeLevelAndEffects");
				if (transform != null)
				{
					transform.GetComponent<Canvas>().enabled = false;
				}
			}
			List<GameObject> activeCorruptedAnimals = ReferenceSingleton<AssetsReference>.Instance.CurrentCorruptedAnimals.activeCorruptedAnimals;
			for (int j = 0; j < activeCorruptedAnimals.Count; j++)
			{
				Transform transform2 = activeCorruptedAnimals[j].transform.Find("CorruptionGaugePanel");
				if (transform2 != null)
				{
					transform2.GetComponent<Canvas>().enabled = false;
				}
			}
			ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.SetActive(value: false);
		}
		catch (Exception ex)
		{
			callback?.Invoke("Error Menu Manager Canvas Group: " + ex.Message);
		}
	}

	private void EnablePlayer(Action<string> callback)
	{
		try
		{
			List<GameObject> activeCompanions = ReferenceSingleton<AssetsReference>.Instance.CurrentCompanions.ActiveCompanions;
			for (int i = 0; i < activeCompanions.Count; i++)
			{
				activeCompanions[i].SetActive(value: true);
				Transform transform = activeCompanions[i].transform.Find("CorruptionGaugeLevelAndEffects");
				if (transform != null)
				{
					transform.GetComponent<Canvas>().enabled = true;
				}
			}
			List<GameObject> activeCorruptedAnimals = ReferenceSingleton<AssetsReference>.Instance.CurrentCorruptedAnimals.activeCorruptedAnimals;
			for (int j = 0; j < activeCorruptedAnimals.Count; j++)
			{
				Transform transform2 = activeCorruptedAnimals[j].transform.Find("CorruptionGaugePanel");
				if (transform2 != null)
				{
					transform2.GetComponent<Canvas>().enabled = true;
				}
			}
			ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.SetActive(value: true);
		}
		catch (Exception ex)
		{
			callback?.Invoke("Error Menu Manager Canvas Group: " + ex.Message);
		}
	}

	private void DisableCameraDice(Action<string> callback)
	{
		try
		{
			if (diceCameraReference.value != null)
			{
				callback?.Invoke("Sucefull DisableCameraDice");
				diceCameraReference.value.gameObject.SetActive(value: false);
			}
		}
		catch (Exception ex)
		{
			callback?.Invoke("Error Menu Manager Canvas Group: " + ex.Message);
		}
	}

	private void EnableCameraDice(Action<string> callback)
	{
		try
		{
			if (diceCameraReference.value != null)
			{
				callback?.Invoke("Sucefull EnableCameraDice");
				diceCameraReference.value.gameObject.SetActive(value: true);
			}
		}
		catch (Exception ex)
		{
			callback?.Invoke("Error Menu Manager Canvas Group: " + ex.Message);
		}
	}

	public void DisableAllMenus()
	{
		try
		{
			bool shouldReturn = false;
			DisableMapCanvas(delegate(bool value)
			{
				if (value)
				{
					menuStack = mapCanvasReference.value;
					shouldReturn = true;
					Debug.Log("[MenuManagerCanvasGroup] DisableMapCanvas");
				}
			});
			DisableGameobjectReference(omenRewardPanelReference, delegate(bool value)
			{
				if (value)
				{
					menuStack = omenRewardPanelReference.value;
					shouldReturn = true;
				}
			});
			DisableGameobjectReference(diceRewardCanvasReference, delegate(bool value)
			{
				if (value)
				{
					menuStack = diceRewardCanvasReference.value;
					shouldReturn = true;
				}
			});
			if (!shouldReturn)
			{
				DisableAllGameplayMenus(disableCamera: true);
			}
		}
		catch (Exception ex)
		{
			Debug.Log("Error Menu Manager Canvas Group: " + ex.Message);
		}
	}

	public void EnableAllMenus()
	{
		try
		{
			if (menuStack == mapCanvasReference.value)
			{
				EnableMapCanvas();
				menuStack = null;
			}
			else if (omenRewardPanelReference.value != null && menuStack == omenRewardPanelReference.value)
			{
				EnableGameobjectReference(omenRewardPanelReference);
				menuStack = null;
			}
			else if (diceRewardCanvasReference.value != null && menuStack == diceRewardCanvasReference.value)
			{
				EnableGameobjectReference(diceRewardCanvasReference);
				menuStack = null;
			}
			else
			{
				EnableAllGameplayMenus(disableCamera: true);
			}
		}
		catch (Exception ex)
		{
			Debug.Log("Error Menu Manager Canvas Group: " + ex.Message);
		}
	}
}
